<script setup lang="ts">
import type { ReportDecisionSupport } from '~/types/api'

defineProps<{ support?: ReportDecisionSupport }>()
const roleColor: Record<string, 'primary' | 'warning' | 'neutral'> = { primary: 'primary', alternative: 'warning', observe: 'neutral' }
function percent(value: number) { return Math.max(0, Math.min(100, Math.round(Number(value || 0) * 100))) }
function coverageLabel(value: number) { const score = percent(value); return score >= 80 ? '依据较完整' : score >= 55 ? '部分可用' : '需要补证' }
</script>

<template>
  <section v-if="support?.target_comparison.length" class="target-comparison" aria-labelledby="target-comparison-title">
    <header><div><span>目标取舍</span><h3 id="target-comparison-title">多目标决策矩阵</h3><p>匹配分用于排序，依据覆盖用于判断“这项排序能信到什么程度”。</p></div><small>{{ support.target_comparison.length }} 个目标</small></header>
    <div class="target-list">
      <article v-for="(row, index) in support.target_comparison" :key="row.job_id" :data-role="row.role">
        <div class="target-order">{{ String(index + 1).padStart(2, '0') }}</div>
        <div class="target-name"><strong>{{ row.display_title }}</strong><UBadge :label="row.role_label" :color="roleColor[row.role]" size="sm" variant="soft" /></div>
        <div class="target-score"><strong>{{ Math.round(row.match_score) }}</strong><span>匹配排序分</span></div>
        <div class="target-focus"><span>优先验证</span><strong>{{ row.top_gap }}</strong></div>
        <div class="target-action"><span>下一行动</span><strong>{{ row.primary_action }}</strong></div>
        <div class="coverage"><div><span>{{ coverageLabel(row.evidence_coverage) }}</span><strong>{{ percent(row.evidence_coverage) }}%</strong></div><div class="coverage-track"><i :style="{ width: `${percent(row.evidence_coverage)}%` }" /></div></div>
      </article>
    </div>
    <div v-if="support.shared_actions.length" class="shared-actions"><div><UIcon name="i-lucide-git-merge" /><strong>可跨目标复用的投入</strong></div><span v-for="item in support.shared_actions" :key="item.dimension"><b>{{ item.label }}</b>{{ item.reason }}</span></div>
  </section>
</template>

